<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {APIError,mutate,request} from './client';
import {errors,messages,folderLabels,type Locale} from './i18n';
const props=defineProps<{locale:Locale;user:any}>();const emit=defineEmits<{expired:[]}>();
const t=computed(()=>messages[props.locale]);const folders=ref<any[]>([]),folder=ref(''),emails=ref<any[]>([]),selected=ref<any>(null),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),position=ref(0),total=ref(0),composing=ref(false),html=ref(false);
const draft=ref<any>({to:'',cc:'',subject:'',text:'',attachments:[]});let generation=0;
const labels=computed(()=>folderLabels[props.locale]);const folderInput=ref('');let timer:ReturnType<typeof setInterval>|undefined;
async function manageFolder(action='create'){busy.value=true;error.value='';try{await mutate('/mail/mailboxes',{...(action==='create'?{}:{id:folder.value}),name:folderInput.value,destroy:action==='delete'});folders.value=(await request('/mail/mailboxes')).mailboxes;if(action==='delete')switchFolder(folders.value.find(x=>x.role==='inbox').id);notice.value=t.value.saved;folderInput.value='';}catch(e){problem(e);}finally{busy.value=false;}}
const errorText=computed(()=>errors[props.locale][error.value]||errors[props.locale].fallback);
function problem(e:unknown){if(e instanceof APIError&&e.status===401){emit('expired');return;}error.value=e instanceof APIError?e.code:'fallback';}
function folderName(box:any){return (t.value as any)[box.role]||box.name;}
async function load(){const own=++generation;busy.value=true;error.value='';try{const data=await request(`/mail/messages?${new URLSearchParams({mailbox:folder.value,q:query.value,position:String(position.value)})}`);if(own===generation){emails.value=data.messages;total.value=data.total||0;}}catch(e){problem(e);}finally{if(own===generation)busy.value=false;}}
async function connect(){busy.value=true;error.value='';try{const data=await request('/mail/mailboxes');folders.value=data.mailboxes;folder.value=folders.value.find(x=>x.role==='inbox')?.id||folders.value[0]?.id||'';if(folder.value)await load();}catch(e){problem(e);}finally{busy.value=false;}}
function switchFolder(id:string){folder.value=id;position.value=0;selected.value=null;composing.value=false;query.value='';load();}
async function read(id:string){busy.value=true;error.value='';try{selected.value=await request(`/mail/messages/${encodeURIComponent(id)}`);html.value=false;composing.value=false;await mutate(`/mail/messages/${encodeURIComponent(id)}`,{seen:true},'PATCH');selected.value.keywords.$seen=true;const item=emails.value.find(x=>x.id===id);if(item)item.keywords.$seen=true;}catch(e){problem(e);}finally{busy.value=false;}}
async function update(change:any){busy.value=true;error.value='';try{await mutate(`/mail/messages/${encodeURIComponent(selected.value.id)}`,change,'PATCH');if(change.mailbox){selected.value=null;await load();}else{if(change.seen!==undefined)selected.value.keywords.$seen=change.seen;if(change.flagged!==undefined)selected.value.keywords.$flagged=change.flagged;await load();}}catch(e){problem(e);}finally{busy.value=false;}}
function compose(kind='new'){
  const previous=selected.value;draft.value={to:'',cc:'',subject:'',text:'',attachments:[]};notice.value='';
  if(previous&&kind==='draft')draft.value={id:previous.id,to:previous.to?.map((x:any)=>x.email).join(', ')||'',cc:previous.cc?.map((x:any)=>x.email).join(', ')||'',subject:previous.subject,text:previous.text,attachments:previous.attachments||[]};
  else if(previous&&kind!=='new'){if(kind!=='forward')draft.value.replyToId=previous.id;const from=previous.from?.map((x:any)=>x.email)||[];draft.value.to=kind==='forward'?'':from.filter((x:string)=>x!==props.user.email).join(', ');if(kind==='replyAll')draft.value.cc=[...(previous.to||[]),...(previous.cc||[])].map((x:any)=>x.email).filter((x:string)=>x!==props.user.email&&!from.includes(x)).join(', ');draft.value.subject=`${kind==='forward'?'Fwd:':'Re:'} ${previous.subject||''}`;draft.value.text=`\n\n> ${(previous.text||'').replaceAll('\n','\n> ')}`;}
  composing.value=true;
}
async function save(send=false){busy.value=true;error.value='';notice.value='';try{const saved=await mutate('/mail/drafts',draft.value);draft.value.id=saved.id;if(send){await mutate('/mail/send',{id:saved.id});notice.value=t.value.sendAccepted;composing.value=false;}else notice.value=t.value.saved;await load();}catch(e){problem(e);}finally{busy.value=false;}}
async function attach(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);busy.value=true;error.value='';try{if(files.length+draft.value.attachments.length>5)throw new APIError('ATTACHMENT_REJECTED',422);for(const file of files){if(file.size>5*1024*1024)throw new APIError('ATTACHMENT_REJECTED',422);const attachment=await request('/mail/upload',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});draft.value.attachments.push(attachment);}}catch(e){problem(e);}finally{busy.value=false;input.value='';}}
function move(role:string){const box=folders.value.find(x=>x.role===role);if(box)update({mailbox:box.id});}
const date=(value:string)=>new Intl.DateTimeFormat(props.locale,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
watch(()=>props.locale,()=>{notice.value='';});onMounted(()=>{connect();timer=setInterval(async()=>{if(!busy.value&&!composing.value&&folders.value.length)try{folders.value=(await request('/mail/mailboxes')).mailboxes;}catch(e){problem(e);}},60000);});onUnmounted(()=>{if(timer)clearInterval(timer);});
</script>
<template>
  <div class="mail-heading"><div><p class="eyebrow">OPENPORTAL</p><h1>{{t.mail}}</h1></div><button class="button" :disabled="busy" @click="folders.length?load():connect()">{{t.refresh}}</button></div><div v-if="error" class="alert" role="alert"><p>{{errorText}}</p><p v-if="['MAIL_NOT_CONFIGURED','MAIL_NOT_PROVISIONED'].includes(error)">{{t.mailSetup}}</p></div><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <details v-if="folders.length" class="folder-manager"><summary>{{labels.manage}}</summary><form class="actions" @submit.prevent="manageFolder()"><label>{{labels.name}}<input v-model="folderInput" maxlength="100" required/></label><button class="button" :disabled="busy">{{labels.create}}</button><template v-if="!folders.find(x=>x.id===folder)?.role"><button type="button" class="button" :disabled="busy||!folderInput.trim()" @click="manageFolder('rename')">{{labels.rename}}</button><button type="button" class="button" :disabled="busy" @click="manageFolder('delete')">{{labels.remove}}</button></template></form></details><div v-if="folders.length" class="mail-layout"><aside class="mail-sidebar"><button class="button primary" @click="compose()">{{t.compose}}</button><nav :aria-label="t.mail"><button v-for="box in folders" :key="box.id" :class="{active:folder===box.id}" @click="switchFolder(box.id)">{{folderName(box)}} <span>{{new Intl.NumberFormat(locale).format(box.unreadEmails||0)}}</span></button></nav></aside>
    <section class="mail-list"><form class="mail-search" @submit.prevent="position=0;load()"><label class="sr-only" for="mail-search">{{t.searchMail}}</label><input id="mail-search" v-model="query" type="search" :placeholder="t.searchMail"/><button class="button">{{t.search}}</button></form><p v-if="busy" role="status">{{t.loading}}</p><p v-else-if="!emails.length">{{t.mailboxEmpty}}</p><button v-for="message in emails" :key="message.id" class="mail-item" :class="{unread:!message.keywords?.$seen,selected:selected?.id===message.id}" @click="read(message.id)"><span>{{message.from?.[0]?.name||message.from?.[0]?.email}}</span><strong>{{message.subject||t.noSubject}}</strong><span>{{message.preview}}</span><time :datetime="message.receivedAt">{{date(message.receivedAt)}}</time></button><div class="pagination"><button v-if="position>0" class="button" @click="position-=30;load()">{{t.previous}}</button><button v-if="position+30<total" class="button" @click="position+=30;load()">{{t.next}}</button></div></section>
    <section class="mail-reader"><form v-if="composing" class="form-stack" @submit.prevent="save(true)"><h2>{{t.compose}}</h2><label>{{t.to}}<input v-model="draft.to" required/></label><label>{{t.cc}}<input v-model="draft.cc"/></label><label>{{t.subject}}<input v-model="draft.subject" maxlength="998"/></label><label>{{t.body}}<textarea v-model="draft.text" rows="14" maxlength="500000"/></label><label>{{t.attachment}}<input type="file" multiple accept=".txt,.pdf,.png,.jpg,.jpeg" :disabled="busy" @change="attach"/></label><small>{{t.attachmentHint}}</small><ul><li v-for="(file,index) in draft.attachments" :key="file.blobId">{{file.name}} <button type="button" class="button" @click="draft.attachments.splice(index,1)">{{t.clear}}</button></li></ul><div class="actions"><button class="button primary" :disabled="busy">{{t.send}}</button><button type="button" class="button" :disabled="busy" @click="save()">{{t.saveDraft}}</button><button type="button" class="button" @click="composing=false">{{t.cancel}}</button></div></form>
      <article v-else-if="selected"><h2>{{selected.subject||t.noSubject}}</h2><p>{{selected.from?.map((x:any)=>x.email).join(', ')}}</p><time :datetime="selected.receivedAt">{{date(selected.receivedAt)}}</time><label>{{labels.move}}<select :aria-label="labels.move" @change="update({mailbox:($event.target as HTMLSelectElement).value})"><option value="" disabled selected>{{labels.move}}</option><option v-for="box in folders" :key="box.id" :value="box.id">{{folderName(box)}}</option></select></label><div class="actions"><button class="button" @click="compose('reply')">{{t.reply}}</button><button class="button" @click="compose('replyAll')">{{t.replyAll}}</button><button class="button" @click="compose('forward')">{{t.forward}}</button><button v-if="selected.keywords?.$draft" class="button" @click="compose('draft')">{{t.compose}}</button><button class="button" @click="update({seen:!selected.keywords?.$seen})">{{selected.keywords?.$seen?t.markUnread:t.markRead}}</button><button class="button" @click="update({flagged:!selected.keywords?.$flagged})">{{selected.keywords?.$flagged?t.unstar:t.star}}</button><button class="button" @click="move('trash')">{{t.moveTrash}}</button><button class="button" @click="move('inbox')">{{t.restore}}</button></div><p class="source-note">{{t.externalImages}}</p><button v-if="selected.html" class="button" @click="html=!html">{{html?t.hideHTML:t.showHTML}}</button><iframe v-if="html" class="mail-html" sandbox="" referrerpolicy="no-referrer" :title="selected.subject||t.body" :srcdoc="`<meta http-equiv='Content-Security-Policy' content=&quot;default-src 'none'; style-src 'none'; img-src 'none'&quot;>${selected.html}`"/><pre v-else class="mail-text">{{selected.text}}</pre><div v-if="selected.attachments?.length"><h3>{{t.attachments}}</h3><a v-for="file in selected.attachments" :key="file.blobId" class="attachment" :href="`/api/v2/mail/attachments/${encodeURIComponent(selected.id)}/${encodeURIComponent(file.blobId)}`">{{file.name}}</a></div></article><p v-else>{{t.chooseMessage}}</p>
    </section>
  </div>
</template>
